import{_ as e,o as i,c as a,a2 as o}from"./chunks/framework.CFuv5BrO.js";const h=JSON.parse('{"title":"Executor Models and Routing","description":"Hearth executor models, capability matrix, routing principles, and how multiple executors collaborate.","frontmatter":{"title":"Executor Models and Routing","description":"Hearth executor models, capability matrix, routing principles, and how multiple executors collaborate.","outline":[2,3]},"headers":[],"relativePath":"en/architecture/executor-model.md","filePath":"en/architecture/executor-model.md","lastUpdated":null}'),d={name:"en/architecture/executor-model.md"};function n(r,t,s,l,c,u){return i(),a("div",null,[...t[0]||(t[0]=[o(`<p class="eyebrow">EXECUTOR MODEL</p><h1 id="executor-model-and-routing" tabindex="-1">Executor Model and Routing <a class="header-anchor" href="#executor-model-and-routing" aria-label="Permalink to &quot;Executor Model and Routing&quot;">​</a></h1><p class="lead">Executors are not a list of Workers; they are peer execution entities with explicit capabilities, risk boundaries, and output contracts.</p><h2 id="executor-is-not-a-worker-list" tabindex="-1">Executor Is Not a Worker List <a class="header-anchor" href="#executor-is-not-a-worker-list" aria-label="Permalink to &quot;Executor Is Not a Worker List&quot;">​</a></h2><p>Hearth uses peer <code>Executor</code>s rather than cramming everything into one &quot;universal Agent&quot;:</p><ul><li><strong>Native Runtime</strong>: built-in general-purpose reasoning and short tool loops;</li><li><strong>Codex Executor</strong>: high-capability workspace Executor covering code, research, and documents;</li><li><strong>Connector Executor</strong>: email, calendar, documents, cloud drives, IM, and Issue Trackers;</li><li><strong>Browser Executor</strong>: web pages, forms, authenticated sessions, and SaaS;</li><li><strong>GUI Executor</strong>: desktop applications without APIs;</li><li><strong>Document/Data Executor</strong>: parsing, transformation, spreadsheets, reconciliation, and deterministic processing;</li><li><strong>Human Executor</strong>: approvals, judgment, takeover, and high-risk accountability.</li></ul><p>A single Task can be handled collaboratively by multiple Executors; Executors do not share credentials, files, or implicit context.</p><h2 id="capability-matrix" tabindex="-1">Capability Matrix <a class="header-anchor" href="#capability-matrix" aria-label="Permalink to &quot;Capability Matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Native</th><th>Codex</th><th>Connector</th><th>Browser</th><th>GUI</th><th>Document/Data</th><th>Human</th></tr></thead><tbody><tr><td>Code, tests, Issues, PRs</td><td>Medium</td><td>High</td><td>Low</td><td>Low</td><td>Low</td><td>Low</td><td>Review</td></tr><tr><td>Research and structured investigation</td><td>High</td><td>High</td><td>Medium</td><td>High</td><td>Low</td><td>Low</td><td>Judgment</td></tr><tr><td>Document generation and editing</td><td>Medium</td><td>High</td><td>Medium</td><td>Medium</td><td>Medium</td><td>High</td><td>Acceptance</td></tr><tr><td>Shell and file conversion</td><td>Medium</td><td>High</td><td>Low</td><td>Low</td><td>Medium</td><td>High</td><td>No</td></tr><tr><td>Email/calendar</td><td>Low</td><td>Low</td><td>High</td><td>Medium</td><td>Medium</td><td>Low</td><td>Approval</td></tr><tr><td>Login and forms</td><td>Low</td><td>Low</td><td>Medium</td><td>High</td><td>Medium</td><td>Low</td><td>Takeover</td></tr><tr><td>Desktop applications</td><td>Low</td><td>Low</td><td>Low</td><td>Low</td><td>High</td><td>Low</td><td>Takeover</td></tr><tr><td>Persistent event handling</td><td>High</td><td>Low</td><td>High</td><td>Low</td><td>Low</td><td>Low</td><td>No</td></tr><tr><td>Long-term memory</td><td>Medium</td><td>Low</td><td>Low</td><td>Low</td><td>Low</td><td>Low</td><td>Review</td></tr><tr><td>High-risk side effects</td><td>Low</td><td>Low</td><td>High</td><td>High</td><td>High</td><td>Low</td><td>High</td></tr></tbody></table><p>The matrix is not a fixed conclusion; it must be updated based on real Tasks and failure data. Codex can receive email, calendar, and document excerpts retrieved by Connectors for understanding, research, and drafting; actual sending, inviting, deleting, or publishing is still handled by Connectors, the Credential Broker, and the approval chain.</p><h2 id="routing-principles" tabindex="-1">Routing Principles <a class="header-anchor" href="#routing-principles" aria-label="Permalink to &quot;Routing Principles&quot;">​</a></h2><p>There is no fixed order of &quot;always use Native first and only use Codex last.&quot; Routing is optimization under hard constraints:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Candidate executors</span></span>
<span class="line"><span>  → capability matching</span></span>
<span class="line"><span>  → permission and data residency checks</span></span>
<span class="line"><span>  → expected success rate</span></span>
<span class="line"><span>  → Token / cost / latency</span></span>
<span class="line"><span>  → risk and reversibility penalty</span></span>
<span class="line"><span>  → select the option that maximizes user value</span></span></code></pre></div><p>Practical decision sequence:</p><ol><li>No model required: cron, rules, SQL, scripts, file diffs, official APIs.</li><li>External data or side effects required: prefer Connector; if there is no API, use Browser; if there is no browser interface, use GUI.</li><li>Deterministic document/data transformation: Document/Data.</li><li>Long task chains, multiple files, multiple Artifacts, complex research, code, or deep writing: Codex.</li><li>High-frequency, short, low-risk, privacy-sensitive, or low-budget reasoning: Native + small/local models.</li><li>Value judgments, accountability, or exception handling: Human.</li></ol><p>Risk, permissions, and data residency are hard constraints; a high score cannot offset them.</p><h2 id="executor-collaboration" tabindex="-1">Executor Collaboration <a class="header-anchor" href="#executor-collaboration" aria-label="Permalink to &quot;Executor Collaboration&quot;">​</a></h2><p>A typical task: “Find information on three competitors, organize it into a comparison table, write it into the weekly report, and email the key conclusions to the team.”</p><p>Possible chain:</p><ol><li>Browser retrieves web pages;</li><li>Native extracts and summarizes;</li><li>Document/Data generates a table;</li><li>Codex handles the long document, formatting, and citations;</li><li>Human approves the email;</li><li>Connector sends it and generates a Receipt;</li><li>Memory records the project background and commitments;</li><li>Evolution observes whether it is worth codifying into a skill.</li></ol><p>Each step has its own inputs, outputs, budget, and validator.</p>`,21)])])}const m=e(d,[["render",n]]);export{h as __pageData,m as default};
